import{z as E,x as u,o as t,c as d,q as s,j as l,D as e,d as i,s as h,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Church–Turing 论题","description":"","frontmatter":{"title":"Church–Turing 论题","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/church-turing-thesis.md","filePath":"cs/church-turing-thesis.md","lastUpdated":1791063341000}'),p={name:"cs/church-turing-thesis.md"};function B(T,a,c,A,m,C){const n=u("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="church–turing-论题" tabindex="-1">Church–Turing 论题 <a class="header-anchor" href="#church–turing-论题" aria-label="Permalink to &quot;Church–Turing 论题&quot;">​</a></h1><div class="epigraph"><p>直观可有效计算的函数，正是图灵机可计算的函数；这是论题，不是定理，但对准了 λ 演算、递归函数与现代程序。</p><footer>—— 据 Church, 1936；Turing, 1936；Sipser 整理</footer></div><p>上一课<a href="/cs/tm-variants">图灵机变体</a>表明带状机器内部怎么改都不扩大 RE。缺口是对外：直觉里的「算法」、λ 项、一般递归，是否同一类。Church–Turing 论题给出对齐。本课不把 λ 演算写完（后单元），只登记论题的用法与边界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Turing 用机器，Church 用 λ 可定义，Kleene 用递归方程，Post 用改写。他们证明这些形式系统两两等价。剩下的一步无法形式化：任何在纸上「逐步、有限、机械」的手续，都能被其中之一模拟。这一步叫论题。<span class="marginnote">术语翻译：「论题」（thesis）与「定理」的区别——定理有严格证明，论题没有，因为「直觉上可逐步执行的手续」这件事本身没有数学定义，无法拿来对齐。所以它是工作约定：被几十年的等价结果反复加固，但原则上不可证。</span>接受它，才能把「不可被 TM 判定」说成「不可被算法判定」。</p><p>主干已经写过程序、编译、操作系统：那些都默认可被 TM 模拟（多项式或多项式等价）。本课不重做 RAM 模拟细节，只声明：<strong>补层后文的否定结果，对算法本身有效</strong>。</p><h3 id="论题不管快慢" tabindex="-1">论题不管快慢 <a class="header-anchor" href="#论题不管快慢" aria-label="Permalink to &quot;论题不管快慢&quot;">​</a></h3><p>「可计算」无资源。多项式时间、随机、量子是后课复杂性对论题的精化（广义 Church–Turing）。本课不把 \\(P\\) 写进来。物理上的模拟器若用连续量或无限精度，也不在论题的「有效」里。</p><p><span class="marginnote">Church 1936 的判定问题；Turing 1936 同时给出停机的形状。Gandy、Sieg 后来分析「机械」的约束。本课用课堂版本：算法 = TM。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出已证等价的形式系统：TM、λ（后课）、部分递归。把论题当成翻译许可证：给出一个清晰的逐步手续，即可说存在 TM，不必画状态表。反之，要证「没有算法」，必须相对某个形式模型——默认 TM。</p>',11)),(t(),l(o,null,{default:e(()=>[h(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INTU%5B%22%E7%9B%B4%E8%A7%89%E7%AE%97%E6%B3%95%22%5D%20--%3E%20THESIS%5B%22Church%E2%80%93Turing%20%E8%AE%BA%E9%A2%98%22%5D%0A%20%20THESIS%20--%3E%20TM%5B%22%E5%9B%BE%E7%81%B5%E6%9C%BA%22%5D%0A%20%20THESIS%20--%3E%20LAM%5B%22%CE%BB%20%2F%20%E9%80%92%E5%BD%92%E5%87%BD%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"不要用论题「证明」停机可解：论题不增加计算能力。它只统一语言。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"有了论题，编码与归约才有权谈任意问题：实例写成串，手续写成 TM。后课对角化攻击的是这个类的完备对象（通用机），不是某一门编程语言。换 Python 或 RISC 指令，只要能互模拟，不可判定一起走。",-1)),a[6]||(a[6]=r("p",null,"不可判定性为什么「跟着语言走」：",-1)),(t(),l(o,null,{default:e(()=>[h(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20PY%5B%22Python%20%E5%86%99%E7%9A%84%E6%89%8B%E7%BB%AD%22%5D%20--%3E%20SIM%5B%22%E4%B8%8E%E5%9B%BE%E7%81%B5%E6%9C%BA%E4%BA%92%E7%9B%B8%E6%A8%A1%E6%8B%9F%22%5D%0A%20%20RISC%5B%22RISC%20%E6%9C%BA%E5%99%A8%E7%A0%81%22%5D%20--%3E%20SIM%0A%20%20LAM%5B%22%CE%BB%20%E6%BC%94%E7%AE%97%E9%A1%B9%22%5D%20--%3E%20SIM%0A%20%20SIM%20--%3E%20HALT%5B%22%E5%81%9C%E6%9C%BA%E9%97%AE%E9%A2%98%E5%AF%B9%E5%85%A8%E4%BD%93%E5%90%8C%E6%A0%B7%E4%B8%8D%E5%8F%AF%E5%88%A4%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>超计算（无穷步、神谕）明确离开论题。本补层不采用。</p><p>论题不禁止你用 Python 或 RISC 想算法，只禁止你把「人类直觉上的逐步手续」说成比 TM 更强。相对化、神谕、无穷时间明确退出「有效」。后课不可判定结果的读法是：没有算法，不是「现在的计算机太慢」。λ 与组合子课会把另一套语法填进已经对齐的类。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 λ 与 TM 的翻译，不讨论相对性论题、物理 Church–Turing。不把论题当成经验科学假说去「实验」。后课默认：可计算 = 某 TM 总停并输出；可识别 = 某 TM 在是实例上停于接受。下一单元第一课切开判定与识别。</p><p>后课每个否定结果都相对 TM（或与之等价的 λ / 递归函数）。换一门编程语言不能绕过停机。论题也不授权把连续物理量当成额外计算资源。<span class="marginnote">常见误区：初学者容易以为「量子计算机能算图灵机算不了的问题」。目前的量子计算并不突破可计算性边界——它能算的图灵机都能算，只是某些问题（如大数分解）快得多。「更强」与「更快」是两回事，前者要动论题，后者属于复杂性课。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>论题：有效可计算 = TM 可计算；等价系统已形式互译。</li><li>否定结果对「算法」生效；论题不谈复杂度。</li><li>不是定理，但是本补层的工作约定。</li><li>出处：Church, 1936；Turing, 1936；Sipser。</li></ul>',7))])}const f=E(p,[["render",B]]);export{S as __pageData,f as default};
